import json,os,stat,subprocess
from pathlib import Path
D="rea-reversa.duckdns.org"
paths=["/etc/rea-reversa","/root/project-secrets/rea-mcp","/etc/nginx/sites-available/"+D+".conf","/etc/nginx/sites-enabled/"+D+".conf","/etc/letsencrypt/renewal/"+D+".conf","/etc/letsencrypt/live/"+D,"/etc/letsencrypt/archive/"+D,"/tmp/runtime-rea-reversa","/tmp/hsperfdata_rea-reversa"]
needles=[b"rea-reversa.duckdns.org",b"/etc/rea-reversa",b"rea-original-upstream-680",b"rea-final-runtime",b"rea-mcp-oauth",b"rea-chatgpt-trial",b"/srv/projects/Engenheira-reversa",b"/srv/projects/REA-Trial"]
def info(p):
 try:
  s=p.lstat()
  return {"type":"symlink" if stat.S_ISLNK(s.st_mode) else "directory" if stat.S_ISDIR(s.st_mode) else "file","uid":s.st_uid,"bytes":s.st_size,"target":os.readlink(p) if p.is_symlink() else None}
 except OSError:return None
def run(a,t=15):
 try:
  r=subprocess.run(a,capture_output=True,text=True,timeout=t)
  return {"exit":r.returncode,"stdout":r.stdout.strip()[:1300],"stderr":r.stderr.strip()[:350]}
 except Exception as e:return {"error":type(e).__name__}
data={"mode":"READ_ONLY","paths":{},"scope":"REA standalone leftovers"}
for s in paths:
 p=Path(s)
 m=info(p)
 if m is not None and p.is_dir() and not p.is_symlink():
  try:
   children=list(p.iterdir())
   m["children"]=[{"name":a.name,"type":(info(a) or {}).get("type"),"bytes":(info(a) or {}).get("bytes")} for a in children[:50]]
   m["child_count"]=len(children)
  except OSError:pass
 data["paths"][s]=m
data["nginx_preflight"]=run(["/usr/sbin/nginx","-t"])
data["certbot_present"]=Path("/usr/bin/certbot").exists()
data["certbot_certificate_names"]=[]
if Path("/usr/bin/certbot").exists():
 q=run(["/usr/bin/certbot","certificates"],18)
 data["certbot_certificate_names"]=[ln.strip() for ln in q.get("stdout","").splitlines() if "Certificate Name:" in ln][:25]
paths_scan=["/etc/systemd/system","/usr/lib/systemd/system","/etc/nginx","/etc/cron.d","/etc/cron.daily","/etc/letsencrypt/renewal","/usr/local/bin","/usr/local/sbin","/home/ubuntu/.config/systemd/user"]
hits=[];files_count=0
for folder in paths_scan:
 p=Path(folder)
 if not p.is_dir():continue
 for cur,ds,fs in os.walk(folder,followlinks=False):
  ds[:]=[x for x in ds if x not in ("backup","backups","archive",".git")]
  for name in fs:
   f=Path(cur)/name
   try:
    if f.is_symlink() or not f.is_file() or f.stat().st_size>160000:continue
    files_count+=1
    b=f.read_bytes()
    found=[x.decode() for x in needles if x in b]
    if found:hits.append({"config_file":str(f),"matched":found})
   except OSError:pass
data["config_refs"]={"scanned":files_count,"matches":hits[:60],"total":len(hits)}
try:
 p=Path("/etc/nginx/sites-available/"+D+".conf")
 if p.is_file() and not p.is_symlink():
  lines=p.read_text(errors="replace").splitlines()
  data["legacy_vhost_selected_directives"]=[x.strip()[:240] for x in lines if x.lstrip().startswith(("server_name ","listen ","proxy_pass ","ssl_certificate ","ssl_certificate_key ","root ","return ","include "))][:30]
except OSError:pass
units=run(["/usr/bin/systemctl","list-unit-files","--all","--no-legend","--no-pager"],18)
data["units_legacy"]=[x for x in units.get("stdout","").splitlines() if "rea" in x.lower() or "trial" in x.lower()]
status=run(["/usr/bin/systemctl","list-units","--all","--no-legend","--no-pager"],18)
data["loaded_units_legacy"]=[x for x in status.get("stdout","").splitlines() if "rea" in x.lower() or "trial" in x.lower()]
hot=[]
for f in Path("/proc").iterdir():
 if not f.name.isdecimal():continue
 try:
  c=(f/"cmdline").read_bytes().lower()
  if any(k in c for k in (b"/tmp/runtime-rea-reversa",b"/tmp/hsperfdata_rea-reversa",b"rea-final-runtime",b"/srv/projects/rea-trial")):
   hot.append({"pid":int(f.name),"name":(f/"comm").read_text().strip()[:60]})
 except OSError:pass
data["active_legacy_processes"]=hot[:30]
data["journal_retention"]=run(["/usr/bin/journalctl","--disk-usage"],12)
data["apt_cache_listing"]=[{"file":x.name,"bytes":x.stat().st_size} for x in Path("/var/cache/apt/archives").iterdir() if x.is_file()][:20] if Path("/var/cache/apt/archives").is_dir() else []
print(json.dumps(data,ensure_ascii=True,sort_keys=True))
